import type { LocalAiMode, LocalAiSetup, LocalAiState } from '@motivation/shared';
import { API_URL } from '../config.js';
import { createJsonClient } from './http.js';

const api = createJsonClient(`${API_URL}/api/ai`);

/** Story 426: the Local AI switch. Server-only — offline it fails as the browser's network error. */
export class AiService {
    static async getLocalAi(): Promise<LocalAiState> {
        return api.get<LocalAiState>('/local-ai');
    }

    /**
     * Answers once the chat server is up; a failed start rejects with the sidecar's raw error.
     * Story 427: `setup` picks the chat server's start flags; the server ignores it for `off`.
     */
    static async setLocalAi(mode: LocalAiMode, setup: LocalAiSetup = 'app'): Promise<LocalAiState> {
        return api.put<LocalAiState>('/local-ai', { mode, setup });
    }

    /**
     * Story 429: llama.cpp's web UI through the backend's pass-through. The trailing slash matters:
     * the web UI takes its base from its own URL.
     */
    static chatUrl(): string {
        return `${API_URL}/llama/`;
    }
}
